public Money Total()
{
    if (!IsValid()) return Money.Zero;
    return Discounted(Subtotal());
}

private bool IsValid() => _lines.Count > 0;
private Money Subtotal() => _lines.Sum(line => line.Amount);
private Money Discounted(Money subtotal) => subtotal - _discount;

